CREATE TABLE categorias(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(150));
CREATE TABLE productos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(150) NOT NULL,precio NUMERIC(10,2) NOT NULL CHECK(precio>=0),categoria_id BIGINT REFERENCES categorias(id));
